// =============================== Test Fixture ===============================

class XzraTest : public ::testing::Test {
   protected:
    static constexpr int kDefaultNumThreads = 1;  // Single threaded
    static constexpr uint64_t kDefaultDecompMemLimit = 50ULL << 20;  // 50 MiB
    static constexpr size_t kDummyDataSize = (3ULL << 20) + 43;      // >3 MiB
    static constexpr uint32_t kDefaultBlockSize = 1U << 20;          // 1 MiB
    static constexpr uint32_t kDefaultLevel = 6;  // Default level

    std::string dummy_in_file;           /**< Name for the uncompressed file */
    std::string dummy_out_file;          /**< Name for the compressed file */
    std::string dummy_decompressed_file; /**< Name for the decompressed file */

    XzraCodecOptions default_options; /**< 1 MiB blocks, level 6, 1 thread */
    std::vector<uint8_t> test_data;   /**< Random dummy data for compression */

    void SetUp() override {
        // 1. Generate unique filenames based on the current test suite and test
        // name
        const ::testing::TestInfo *test_info =
            ::testing::UnitTest::GetInstance()->current_test_info();
        std::string test_prefix =
            std::string(test_info->test_suite_name()) + "_" + test_info->name();

        dummy_in_file = test_prefix + "_in.dat";
        dummy_out_file = test_prefix + "_out.xz";
        dummy_decompressed_file = test_prefix + "_decompressed.dat";

        // 2. Initialize default options
        default_options.block_size = kDefaultBlockSize;
        default_options.level = kDefaultLevel;
        default_options.extreme = false;
        default_options.num_threads = kDefaultNumThreads;

        // 3. Generate predictable dummy data
        test_data.resize(kDummyDataSize);
        for (size_t i = 0; i < test_data.size(); ++i) {
            test_data[i] = static_cast<uint8_t>(i & UINT8_MAX);
        }

        // 4. Write to the dummy input file
        std::ofstream ofs(dummy_in_file, std::ios::binary);
        ofs.write(reinterpret_cast<const char *>(test_data.data()),
                  test_data.size());
        ofs.close();
    }

    void TearDown() override {
        // Clean up the temporary files
        std::remove(dummy_in_file.c_str());
        std::remove(dummy_out_file.c_str());
        std::remove(dummy_decompressed_file.c_str());
    }
};

