// Tests successful file-to-file compression and verifies the output size
TEST_F(XzraTest, CompressFileSuccess) {
    uint64_t out_size = 0;
    XzraStatus status =
        XzraCompressFile(dummy_out_file.c_str(), dummy_in_file.c_str(),
                         &default_options, &out_size);

    EXPECT_EQ(status, XZRA_SUCCESS);
    EXPECT_GT(out_size, 0ULL) << "Output size should be strictly greater than "
                                 "0 upon successful compression.";

    // Verify the file was actually created on disk and its size matches
    // out_size
    std::ifstream ifs(dummy_out_file, std::ios::binary | std::ios::ate);
    ASSERT_TRUE(ifs.is_open())
        << "The compressed output file should exist and be readable.";

    std::streamsize actual_file_size = ifs.tellg();
    ifs.close();

    EXPECT_EQ(static_cast<uint64_t>(actual_file_size), out_size)
        << "Reported out_size should exactly match the size of the file on "
           "disk.";
}

