// Tests creating a stream and writing data in multiple smaller chunks
TEST_F(XzraTest, StreamRunMultipleChunks) {
    XzraOutStream *stream =
        XzraOutStreamCreate(dummy_out_file.c_str(), &default_options);
    ASSERT_NE(stream, nullptr);

    // Use an irregular chunk size to test the behavior in general cases
    const size_t chunk_size = (1ULL << 20) - 3;
    uint64_t cumulative_written = 0;

    for (size_t offset = 0; offset < test_data.size(); offset += chunk_size) {
        size_t current_chunk = std::min(chunk_size, test_data.size() - offset);
        uint64_t bytes_written = 0;

        XzraStatus status = XzraOutStreamRun(stream, test_data.data() + offset,
                                             current_chunk, &bytes_written);
        EXPECT_EQ(status, XZRA_SUCCESS);
        cumulative_written += bytes_written;
    }

    uint64_t total_bytes = 0;
    XzraStatus status = XzraOutStreamClose(stream, &total_bytes);

    EXPECT_EQ(status, XZRA_SUCCESS);
    EXPECT_GE(total_bytes, cumulative_written);

    std::ifstream ifs(dummy_out_file, std::ios::binary | std::ios::ate);
    ASSERT_TRUE(ifs.is_open());
    EXPECT_EQ(static_cast<uint64_t>(ifs.tellg()), total_bytes);
    ifs.close();
}

