// Tests XzraOutStreamAbort to ensure memory is freed and the file isn't
// finalized to disk
TEST_F(XzraTest, StreamAbortMidway) {
    XzraOutStream *stream =
        XzraOutStreamCreate(dummy_out_file.c_str(), &default_options);
    ASSERT_NE(stream, nullptr);

    uint64_t bytes_written = 0;
    XzraStatus status = XzraOutStreamRun(stream, test_data.data(),
                                         test_data.size() / 2, &bytes_written);
    EXPECT_EQ(status, XZRA_SUCCESS);

    XzraOutStreamAbort(stream);

    // Depending on OS and C library buffering, the file on disk may be empty or
    // contain partial blocks, but it should definitely lack the mandatory XZ
    // footer. The primary goal here is to ensure the Abort call does not cause
    // a segmentation fault.
    SUCCEED() << "XzraOutStreamAbort completed without crashing.";
}

// Tests streaming compression with a single massive chunk and verifies data
