// Tests streaming compression with randomized or irregular chunk sizes to
// stress internal buffer transitions.
TEST_F(XzraTest, StreamRunIrregularChunksRoundTrip) {
    XzraOutStream *stream =
        XzraOutStreamCreate(dummy_out_file.c_str(), &default_options);
    ASSERT_NE(stream, nullptr);

    // Using prime numbers and weird fractions to ensure boundaries never align
    // perfectly with typical internal 4K/1M dictionary limits.
    const size_t chunks[] = {3, 1024, 7777, 1048576, 13, 999999};
    const int num_patterns = sizeof(chunks) / sizeof(chunks[0]);

    size_t offset = 0;
    int pattern_idx = 0;

    while (offset < test_data.size()) {
        size_t current_chunk = std::min(chunks[pattern_idx % num_patterns],
                                        test_data.size() - offset);
        XzraOutStreamRun(stream, test_data.data() + offset, current_chunk,
                         nullptr);
        offset += current_chunk;
        pattern_idx++;
    }
    XzraOutStreamClose(stream, nullptr);

    std::vector<uint8_t> decompressed(test_data.size());
    uint64_t decomp_size = 0;
    XzraDecompressFile(decompressed.data(), dummy_out_file.c_str(),
                       decompressed.size(), kDefaultNumThreads,
                       kDefaultDecompMemLimit, &decomp_size);

    EXPECT_EQ(std::memcmp(decompressed.data(), test_data.data(), decomp_size),
              0)
        << "Irregular chunked compression must not drop or corrupt bytes "
           "spanning internal block limits.";
}

// Tests extreme fragmentation by feeding the compressor byte-by-byte to
// validate state preservation.
TEST_F(XzraTest, StreamRunByteByByteRoundTrip) {
    XzraOutStream *stream =
        XzraOutStreamCreate(dummy_out_file.c_str(), &default_options);
    ASSERT_NE(stream, nullptr);

    // Restricting to a 16 KiB subset of test_data to prevent the test suite
    // from hanging due to the sheer overhead of 10 million function calls and
    // context switches.
    const size_t extreme_test_size = 16384;
    for (size_t i = 0; i < extreme_test_size; ++i) {
        XzraOutStreamRun(stream, test_data.data() + i, 1, nullptr);
    }
    XzraOutStreamClose(stream, nullptr);

    std::vector<uint8_t> decompressed(extreme_test_size);
    uint64_t decomp_size = 0;
    XzraDecompressFile(decompressed.data(), dummy_out_file.c_str(),
                       decompressed.size(), kDefaultNumThreads,
                       kDefaultDecompMemLimit, &decomp_size);

    EXPECT_EQ(decomp_size, extreme_test_size);
    EXPECT_EQ(std::memcmp(decompressed.data(), test_data.data(), decomp_size),
              0)
        << "Byte-by-byte compression must perfectly preserve the LZMA2 state "
           "machine.";
}

// Tests that injecting 0-byte writes into the stream doesn't corrupt the
// compression state or dictionary.
TEST_F(XzraTest, StreamRunZeroByteChunksRoundTrip) {
    XzraOutStream *stream =
        XzraOutStreamCreate(dummy_out_file.c_str(), &default_options);
    ASSERT_NE(stream, nullptr);

    const size_t half_size = test_data.size() / 2;

    // Write first half
    XzraOutStreamRun(stream, test_data.data(), half_size, nullptr);

    // Inject multiple 0-byte operations to simulate spurious wakeups in
    // non-blocking event loops
    XzraOutStreamRun(stream, test_data.data(), 0, nullptr);
    XzraOutStreamRun(stream, nullptr, 0, nullptr);
    XzraOutStreamRun(stream, test_data.data() + half_size, 0, nullptr);

    // Write second half
    XzraOutStreamRun(stream, test_data.data() + half_size,
                     test_data.size() - half_size, nullptr);
    XzraOutStreamClose(stream, nullptr);

    std::vector<uint8_t> decompressed(test_data.size());
    uint64_t decomp_size = 0;
    XzraDecompressFile(decompressed.data(), dummy_out_file.c_str(),
                       decompressed.size(), kDefaultNumThreads,
                       kDefaultDecompMemLimit, &decomp_size);

    EXPECT_EQ(std::memcmp(decompressed.data(), test_data.data(), decomp_size),
              0)
        << "Zero-byte writes should be treated as no-ops and must not inject "
           "garbage into the stream.";
}

