// Tests XzraDecompressFile on a corrupted XZ file (Expect XZRA_ERR_CODEC)
TEST_F(XzraTest, DecompressFileCorruptedInput) {
    std::ofstream ofs(dummy_out_file, std::ios::binary);
    ASSERT_TRUE(ofs.is_open());
    const char content[] = "This is definitely not a valid XZ stream header...";
    ofs.write(content, sizeof(content));
    ofs.close();

    std::vector<uint8_t> dest(1024);
    uint64_t decompressed_size = 0;

    XzraStatus status = XzraDecompressFile(
        dest.data(), dummy_out_file.c_str(), dest.size(), kDefaultNumThreads,
        kDefaultDecompMemLimit, &decompressed_size);

    EXPECT_EQ(status, XZRA_ERR_CODEC)
        << "Decompressor should reject inputs that lack the proper XZ magic "
           "bytes or structure.";
}

